diff --git a/src/common/IntlUtil.cpp b/src/common/IntlUtil.cpp
index 4fabc751b3a..a17c249346f 100644
--- a/src/common/IntlUtil.cpp
+++ b/src/common/IntlUtil.cpp
@@ -591,19 +591,6 @@ ULONG IntlUtil::toUpper(Jrd::CharSet* cs, ULONG srcLen, const UCHAR* src, ULONG
 }


-void IntlUtil::toUpper(Jrd::CharSet* cs, string& s)
-{
-	HalfStaticArray<UCHAR, BUFFER_SMALL> buffer;
-	FB_SIZE_T len = s.length();
-	ULONG count = toUpper(cs, len, (const UCHAR*) s.c_str(), len * 4, buffer.getBuffer(len * 4), NULL);
-
-	if (count != INTL_BAD_STR_LENGTH)
-		s.assign(buffer.begin(), count);
-	else
-		fb_assert(false);
-}
-
-
 bool IntlUtil::readOneChar(Jrd::CharSet* cs, const UCHAR** s, const UCHAR* end, ULONG* size)
 {
 	(*s) += *size;
diff --git a/src/common/IntlUtil.h b/src/common/IntlUtil.h
index 2548dc3d769..df564366d92 100644
--- a/src/common/IntlUtil.h
+++ b/src/common/IntlUtil.h
@@ -84,7 +84,20 @@ class IntlUtil
 		const ULONG* exceptions);
 	static ULONG toUpper(Jrd::CharSet* cs, ULONG srcLen, const UCHAR* src, ULONG dstLen, UCHAR* dst,
 		const ULONG* exceptions);
-	static void toUpper(Jrd::CharSet* cs, string& s);
+
+	template <typename STR>
+	static void toUpper(STR& s, Jrd::CharSet* cs = getUtf8CharSet())
+	{
+		HalfStaticArray<UCHAR, BUFFER_SMALL> buffer;
+		FB_SIZE_T len = s.length();
+		ULONG count = toUpper(cs, len, reinterpret_cast<const UCHAR*>(s.c_str()), len * 4,
+			buffer.getBuffer(len * 4), NULL);
+
+		if (count != INTL_BAD_STR_LENGTH)
+			s.assign(reinterpret_cast<const char*>(buffer.begin()), count);
+		else
+			fb_assert(false);
+	}

 	static bool readOneChar(Jrd::CharSet* cs, const UCHAR** s, const UCHAR* end, ULONG* size);

